class Shape {                        // contract: no data members, no body
public:
    virtual ~Shape() = default;      // safe polymorphic deletion
    Shape(const Shape&) = delete;    // copies would slice
    virtual double area() const = 0; // pure virtual -> Shape is abstract
};
class Square final : public Shape {  // state lives in the implementation
    double side_;
public:
    explicit Square(double s) : side_(s) {}
    double area() const override { return side_ * side_; }
};

