template<class T>
concept Drawable = requires(const T& t) {   // compile-time contract
    { t.area() } -> std::convertible_to<double>;
    t.draw();
};

template<Drawable D>                        // static dispatch: no vtable
void render(const D& shape) { shape.draw(); }

